 1	<?php
 2	/**
 3	 * @package Countries
 4	 * @subpackage API
 5	 */
 6	
 7	declare(strict_types=1);
 8	
 9	namespace Application\Countries\API\Params;
10	
11	use Application\API\Parameters\Handlers\BaseParamHandler;
12	use Application_Countries_Country;
13	use AppUtils\ClassHelper;
14	
15	/**
16	 * Handler that bridges {@see AppCountryIDsParam} into a
17	 * {@see \Application\API\Parameters\Handlers\BaseParamsHandlerContainer}.
18	 *
19	 * Provides type-narrowed overrides for {@see register()} and {@see getParam()}
20	 * so consumers receive a typed `AppCountryIDsParam` without casting.
21	 *
22	 * @package Countries
23	 * @subpackage API
24	 * @see AppCountryIDsParam
25	 */
26	class AppCountryIDsHandler extends BaseParamHandler
27	{
28	    /**
29	     * Resolves the list of countries from the registered parameter.
30	     *
31	     * Returns `null` when the parameter has no value so that the
32	     * {@see \Application\API\Parameters\Handlers\BaseParamsHandlerContainer}
33	     * "first non-null wins" iteration can fall through to the next handler
34	     * (e.g. {@see AppCountryISOsHandler}).
35	     *
36	     * @return Application_Countries_Country[]|null
37	     */
38	    protected function resolveValueFromSubject(): ?array
39	    {
40	        $param = $this->getParam();
41	
42	        if($param === null || $param->getValue() === null) {
43	            return null;
44	        }
45	
46	        return $param->getCountries();
47	    }
48	
49	    /**
50	     * Registers the parameter and returns it type-narrowed.
51	     *
52	     * @return AppCountryIDsParam
53	     */
54	    public function register(): AppCountryIDsParam
55	    {
56	        return ClassHelper::requireObjectInstanceOf(
57	            AppCountryIDsParam::class,
58	            parent::register()
59	        );
60	    }
61	
62	    /**
63	     * Returns the registered parameter type-narrowed, or `null` if not yet registered.
64	     *
65	     * @return AppCountryIDsParam|null
66	     */
67	    public function getParam(): ?AppCountryIDsParam
68	    {
69	        $param = parent::getParam();
70	
71	        if($param instanceof AppCountryIDsParam) {
72	            return $param;
73	        }
74	
75	        return null;
76	    }
77	
78	    protected function createParam(): AppCountryIDsParam
79	    {
80	        return new AppCountryIDsParam();
81	    }
82	}

