 41	    use JSONResponseTrait;
 42	    use AppCountriesAPITrait;
 43	
 44	    public const string METHOD_NAME = 'TestGetCountries';
 45	    public const string VERSION_1_0 = '1.0';
 46	    public const string CURRENT_VERSION = self::VERSION_1_0;
 47	    public const array VERSIONS = array(
 48	        self::VERSION_1_0
 49	    );
 50	
 51	    const string KEY_COUNTRY_IDS = 'countryIDs';
 52	
 53	    public function getMethodName(): string
 54	    {
 55	        return self::METHOD_NAME;
 56	    }
 57	
 58	    public function getDescription(): string
 59	    {
 60	        return 'Test API method for resolving multiple countries individually (no OrRule).';
 61	    }
 62	
 63	    public function getRelatedMethodNames(): array
 64	    {
 65	        return array();
 66	    }
 67	
 68	    public function getVersions(): array
