 79	    {
 80	        return TestDriverAPIGroup::create();
 81	    }
 82	
 83	    protected function init(): void
 84	    {
 85	        $this->manageAppCountriesParams()->manageIDs()->register();
 86	        $this->manageAppCountriesParams()->manageISOs()->register();
 87	    }
 88	
 89	    protected function collectRequestData(string $version): void
 90	    {
 91	    }
 92	
 93	    protected function collectResponseData(ArrayDataCollection $response, string $version): void
