18	 *
19	 * @package API
20	 * @subpackage Parameters
21	 */
22	abstract class BaseParamHandler extends BaseAPIHandler implements ParamHandlerInterface
23	{
24	    private ?APIParameterInterface $param = null;
25	
26	    public function register() : APIParameterInterface
27	    {
28	        if(!isset($this->param)) {
29	            $this->param = $this->createParam();
30	            $this->manager->registerParam($this->param);
31	        }
32	
33	        return $this->param;
34	    }
