36	    /**
37	     * Create an instance of the parameter this handler manages.
38	     * @return APIParameterInterface
39	     */
40	    abstract protected function createParam() : APIParameterInterface;
41	
42	    public function getParam() : ?APIParameterInterface
43	    {
44	        return $this->param;
45	    }
46	
47	    public function requireParam() : APIParameterInterface
48	    {
49	        $param = $this->getParam();
50	
51	        if($param !== null) {
52	            return $param;
53	        }
54	
55	        throw new APIParameterException(
56	            'Requested parameter has not been registered.',
57	            sprintf(
58	                'In handler class [%s].',
59	                get_class($this)
60	            ),
61	            APIParameterException::ERROR_PARAM_NOT_REGISTERED
62	        );
63	    }
64	
65	    public function getParams() : array
66	    {
67	        if(isset($this->param)) {
